/* Generated by tools/gen_keymap.py from keys/layout.py (logical layout),
 * hardware/gen/design.py (LAYOUT: PCB key order, matrix wiring) and
 * hardware/pinmap/pinmap.py (KEY_ROWS/KEY_COLS). Do not edit. */
#ifndef KEYMAP_GEN_H
#define KEYMAP_GEN_H
#include <stdint.h>

#define KEYPAD_ROWS 7
#define KEYPAD_COLS 7

enum key_code {
    KEY_NONE = 0,
    KEY_F1 = 1,  /* row 0 col 0: F1 */
    KEY_F2 = 2,  /* row 0 col 1: F2 */
    KEY_F3 = 3,  /* row 0 col 2: F3 */
    KEY_F4 = 4,  /* row 0 col 3: F4 */
    KEY_F5 = 5,  /* row 0 col 4: F5 */
    KEY_SHIFT = 6,  /* row 0 col 5: shift */
    KEY_ALPHA = 7,  /* row 0 col 6: alpha */
    KEY_DEL = 8,  /* row 1 col 0: ⌫ */
    KEY_HOME = 9,  /* row 1 col 1: home */
    KEY_APPS = 10,  /* row 1 col 2: apps */
    KEY_MENU = 11,  /* row 1 col 3: menu */
    KEY_UP = 12,  /* row 1 col 4: ▲ */
    KEY_LEFT = 13,  /* row 1 col 5: ◀ */
    KEY_RIGHT = 14,  /* row 1 col 6: ▶ */
    KEY_DOWN = 15,  /* row 2 col 0: ▼ */
    KEY_CAS = 16,  /* row 2 col 1: CAS */
    KEY_MATH = 17,  /* row 2 col 2: math */
    KEY_VARS = 18,  /* row 2 col 3: vars */
    KEY_X = 19,  /* row 2 col 4: x */
    KEY_CLEAR = 20,  /* row 2 col 5: clear */
    KEY_SIN = 21,  /* row 2 col 6: sin */
    KEY_COS = 22,  /* row 3 col 0: cos */
    KEY_TAN = 23,  /* row 3 col 1: tan */
    KEY_LN = 24,  /* row 3 col 2: ln */
    KEY_LOG = 25,  /* row 3 col 3: log */
    KEY_SQR = 26,  /* row 3 col 4: x² */
    KEY_POW = 27,  /* row 3 col 5: xʸ */
    KEY_LPAREN = 28,  /* row 3 col 6: ( */
    KEY_RPAREN = 29,  /* row 4 col 0: ) */
    KEY_DIV = 30,  /* row 4 col 1: ÷ */
    KEY_SQRT = 31,  /* row 4 col 2: √ */
    KEY_7 = 32,  /* row 4 col 3: 7 */
    KEY_8 = 33,  /* row 4 col 4: 8 */
    KEY_9 = 34,  /* row 4 col 5: 9 */
    KEY_MUL = 35,  /* row 4 col 6: × */
    KEY_COMMA = 36,  /* row 5 col 0: , */
    KEY_4 = 37,  /* row 5 col 1: 4 */
    KEY_5 = 38,  /* row 5 col 2: 5 */
    KEY_6 = 39,  /* row 5 col 3: 6 */
    KEY_SUB = 40,  /* row 5 col 4: − */
    KEY_ASSIGN = 41,  /* row 5 col 5: → */
    KEY_1 = 42,  /* row 5 col 6: 1 */
    KEY_2 = 43,  /* row 6 col 0: 2 */
    KEY_3 = 44,  /* row 6 col 1: 3 */
    KEY_ADD = 45,  /* row 6 col 2: + */
    KEY_0 = 46,  /* row 6 col 3: 0 */
    KEY_DOT = 47,  /* row 6 col 4: . */
    KEY_NEG = 48,  /* row 6 col 5: (−) */
    KEY_ENTER = 49,  /* row 6 col 6: enter */
    KEY_ON = 50,  /* PA0/WKUP1, not in matrix: on */
    KEY_COUNT = 51
};

#define KEY_IS_SOFT(k) ((k) >= KEY_F1 && (k) <= KEY_F5)
#define KEY_SOFT_INDEX(k) ((k) - KEY_F1)

/* key_matrix[row][col] -> key code */
extern const uint8_t key_matrix[KEYPAD_ROWS][KEYPAD_COLS];
/* key code -> (row << 4 | col), 0xFF if not in the matrix */
extern const uint8_t key_pos[KEY_COUNT];
/* key code -> canonical name (keys/layout.py) */
extern const char *const key_names[KEY_COUNT];
/* alias table for the console: {alias, key} pairs, NULL-terminated */
typedef struct { const char *alias; uint8_t key; } key_alias_t;
extern const key_alias_t key_aliases[];

/* What each key is (keys/layout.py): legends, the text it types, global
 * actions (app/keys.c), per layer. NULL: nothing in that layer. */
typedef struct {
    const char *legend;                   /* keycap */
    const char *text, *suffix;            /* plain: inserted before / after the cursor */
    const char *action;                   /* plain: global action (app/keys.c) */
    const char *shift;                    /* SHIFT legend */
    const char *shift_text, *shift_suffix;
    const char *shift_action;
    const char *alpha;                    /* ALPHA character (UTF-8, lower case) */
} key_info_t;
extern const key_info_t key_info[KEY_COUNT];

/* Matrix pins (port letter, pin number), rows open-drain outputs, columns pull-up inputs */
#define KEY_ROW_PORTS {'G', 'G', 'G', 'G', 'B', 'B', 'B'}
#define KEY_ROW_PINS  {11, 12, 13, 14, 0, 1, 4}
#define KEY_COL_PORTS {'E', 'E', 'E', 'E', 'E', 'B', 'B'}
#define KEY_COL_PINS  {2, 3, 4, 5, 6, 12, 13}

#endif
